# Replace all plain commit hashes like `46c14a7` with hyperlinked ones [`46c14a7`](https://github.com/krishna-mk-0124/Prompt_Insights/commit/46c14a7)
# But only if they are not already hyperlinked!
def hyperlink_match(match):
    full_text = match.group(0)
    hash_val = match.group(1)
    if '](http' in full_text:
        return full_text
    return f"[`{hash_val}`](https://github.com/krishna-mk-0124/Prompt_Insights/commit/{hash_val})"

# Look for | `hash` | at the end of the line
content = re.sub(r'\|\s*`([a-f0-9]{7,40})`\s*\|', r'| [`\1`](https://github.com/krishna-mk-0124/Prompt_Insights/commit/\1) |', content)

